import {readFile,readdir} from 'node:fs/promises';
import {build} from 'esbuild';
const root=new URL('../',import.meta.url),types={html:'text/html; charset=utf-8',css:'text/css; charset=utf-8',js:'application/javascript; charset=utf-8',mjs:'application/javascript; charset=utf-8',svg:'image/svg+xml',txt:'text/plain; charset=utf-8'};
export async function bundleWorker(){const assets={};for(const name of await readdir(new URL('public/',root))){if(!/\.(html|css|js|mjs|svg|txt)$/.test(name))continue;assets['/'+name]={content:await readFile(new URL('public/'+name,root),'utf8'),type:types[name.split('.').at(-1)]};}const contents=(await readFile(new URL('worker/index.js',root),'utf8')).replace('/*__STUDIUM_ASSETS__*/{}',()=>JSON.stringify(assets));const result=await build({stdin:{contents,resolveDir:new URL('worker/',root).pathname,sourcefile:'index.js'},bundle:true,write:false,format:'esm',platform:'browser',target:'es2022'});return {source:result.outputFiles[0].text,assetCount:Object.keys(assets).length};}
